// Adaptive background sync with Exponential Backoff Strategy to handle unstable hotspot/cellular networks
let currentSyncDelay = 8000;
const MIN_SYNC_DELAY = 8000;
const MAX_SYNC_DELAY = 128000;

async function runBackgroundSync() {
  if (!state.enableBackgroundSync || state.networkMode === "offline") {
    setTimeout(runBackgroundSync, MIN_SYNC_DELAY);
    return;
  }
  if (state.token) {
    const oldKotsCount = (state.kots || []).length;
    const oldNotifsCount = (state.notifications || []).filter(n => n.type === "kot_new" || n.type === "kot_ready").length;
    const oldCustomerOrdersCount = (state.notifications || []).filter(n => n.type === "customer_order" && !n.read).length;
    const oldKitchenAlarmsCount = (state.notifications || []).filter(n => n.type === "kitchen_alarm" && !n.read).length;
    
    try {
      // Perform lightweight operational sync
      await refreshOperationalData(true);
      
      // Success! Reset backoff delay
      currentSyncDelay = MIN_SYNC_DELAY;
      
      const newKotsCount = (state.kots || []).length;
      const newNotifsCount = (state.notifications || []).filter(n => n.type === "kot_new" || n.type === "kot_ready").length;
      const newCustomerOrdersCount = (state.notifications || []).filter(n => n.type === "customer_order" && !n.read).length;
      const newKitchenAlarmsCount = (state.notifications || []).filter(n => n.type === "kitchen_alarm" && !n.read).length;
      
      if (newKitchenAlarmsCount > oldKitchenAlarmsCount) {
        playAlarmSound();
      } else if (newCustomerOrdersCount > oldCustomerOrdersCount) {
        playOrderSound();
      } else if ((newKotsCount > oldKotsCount && oldKotsCount > 0) || (newNotifsCount > oldNotifsCount && oldNotifsCount > 0)) {
        playOrderSound();
      }
      
      const isEditing = document.activeElement && ["INPUT", "TEXTAREA", "SELECT"].includes(document.activeElement.tagName.toUpperCase());
      if (["kitchen", "notifications", "delivery", "dashboard"].includes(state.activeView) && !state.modal && !isEditing) {
        render();
      }
    } catch (err) {
      console.warn("[Background Sync] Error occurred, increasing backoff interval:", err);
      logConnectionError("sync_error", err);
      currentSyncDelay = Math.min(currentSyncDelay * 2, MAX_SYNC_DELAY);
    }
  }
  setTimeout(runBackgroundSync, currentSyncDelay);
}
// Start adaptive background scheduler
setTimeout(runBackgroundSync, MIN_SYNC_DELAY);

// Helper to calculate and format countdown timer HTML for KDS
function getKotTimerHtml(createdAt, targetMins, isDefaultTarget, status) {
  const createdDate = new Date(createdAt);
  const elapsedMs = Date.now() - createdDate.getTime();
  const elapsedMins = Math.floor(elapsedMs / 60000);
  const targetMinsNum = Number(targetMins) || 15;
  const remainingMins = targetMinsNum - elapsedMins;
  const isDelayed = remainingMins < 0;

  let timerStr = "";
  if (status === "ready") {
    timerStr = "Ready";
  } else if (isDelayed) {
    timerStr = `Delayed by ${Math.abs(remainingMins)}m`;
  } else {
    timerStr = `${remainingMins}m remaining`;
  }

  let placedTime = "";
  try {
    placedTime = createdDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  } catch (e) {}

  let progressPercent = 100;
  if (targetMinsNum > 0) {
    progressPercent = Math.max(0, Math.min(100, (remainingMins / targetMinsNum) * 100));
  }

  let timerColor = "#10b981"; // green
  let progressColor = "#10b981";
  let statusText = "Preparing...";
  let statusBg = "rgba(16, 185, 129, 0.05)";

  if (status === "ready") {
    timerColor = "#3b82f6"; // blue
    progressColor = "#3b82f6";
    statusText = "Ready for Pickup";
    statusBg = "rgba(59, 130, 246, 0.05)";
    progressPercent = 100;
  } else if (isDelayed) {
    timerColor = "#ef4444"; // red
    progressColor = "#ef4444";
    statusText = `DELAYED BY ${Math.abs(remainingMins)}m`;
    statusBg = "rgba(239, 68, 68, 0.05)";
  } else if (remainingMins <= 2) {
    timerColor = "#f59e0b"; // orange/amber
    progressColor = "#f59e0b";
    statusText = "Overdue Soon!";
    statusBg = "rgba(245, 158, 11, 0.05)";
  }

  const targetTag = isDefaultTarget ? `Target: ${targetMinsNum}m (Default)` : `Target: ${targetMinsNum}m`;

  return `
    <div style="margin: 10px 0; padding: 10px; border-radius: 6px; background: ${statusBg}; border: 1px solid ${timerColor}33; transition: all 0.3s ease;">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
        <span style="font-size: 11px; color: #a3a3a3; font-weight: 500;">⏱️ Placed: ${placedTime}</span>
        <span style="font-size: 11px; font-weight: 700; color: ${timerColor};">${targetTag}</span>
      </div>
      
      <div style="display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px;">
        <span style="font-size: 11px; font-weight: 600; color: #a3a3a3;">${status === 'ready' ? 'Status' : 'Time Remaining'}</span>
        <span class="kds-timer-countdown" style="font-family: monospace; font-size: 16px; font-weight: 800; color: ${timerColor}; letter-spacing: 0.5px; text-shadow: 0 0 5px ${timerColor}33;">
          ${timerStr}
        </span>
      </div>

      <!-- Progress Bar -->
      <div style="width: 100%; height: 5px; background: rgba(255,255,255,0.08); border-radius: 3px; overflow: hidden; margin-bottom: 4px;">
        <div class="kds-timer-progress" style="width: ${progressPercent}%; height: 100%; background: ${progressColor}; transition: width 0.5s ease, background-color 0.5s ease; border-radius: 3px;"></div>
      </div>
      
      <div style="display: flex; justify-content: space-between; align-items: center; margin-top: 4px;">
        <span style="font-size: 11px; font-weight: bold; color: ${timerColor}; text-transform: uppercase; letter-spacing: 0.5px;">
          ${status === 'ready' ? 'Ready to Serve' : statusText}
        </span>
        ${isDelayed && status !== 'ready' ? `<span class="blink" style="font-size: 10px; padding: 1px 5px; border-radius: 3px; background: #ef4444; color: #ffffff; font-weight: 800;">RUSH</span>` : ''}
      </div>
    </div>
  `;
}

let recognition = null;

function initSpeechRecognition() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    state.voiceError = "Speech recognition is not supported in this browser.";
    return;
  }
  
  recognition = new SpeechRecognition();
  recognition.continuous = true;
  recognition.interimResults = false;
  recognition.lang = "en-IN"; // Set to Indian English accent for natural recognition of bill numbers in Tamil Nadu

  recognition.onstart = () => {
    state.voiceActive = true;
    if (state.activeView === "pos" || state.activeView === "tables") {
      state.voiceFeedback = "Listening for POS commands (e.g., 'Add two Biriyani')...";
    } else {
      state.voiceFeedback = "Listening for KDS commands (e.g., 'Order 101 ready')...";
    }
    state.voiceError = "";
    render();
  };

  recognition.onresult = async (event) => {
    const resultIndex = event.resultIndex;
    const transcript = event.results[resultIndex][0].transcript.toLowerCase().trim();
    console.log("Voice command transcript:", transcript);
    state.voiceFeedback = `Heard: "${transcript}"`;
    render();

    // Parse POS/Tables commands if current active view is 'pos' or 'tables'
    const isPosOrTables = state.activeView === "pos" || state.activeView === "tables";
    if (isPosOrTables && (transcript.includes("add") || transcript.includes("add ") || transcript.includes("ஆட்") || transcript.includes("சேர்"))) {
      let command = transcript.replace(/^(add|add to cart|add item|ஆட்|சேர்)\s+/i, "").trim();
      
      const wordToNum = {
        "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
        "single": 1, "double": 2, "triple": 3, "ஒரு": 1, "இரண்டு": 2, "மூன்று": 3, "நான்கு": 4, "ஐந்து": 5
      };
      
      let qty = 1;
      const words = command.split(/\s+/);
      const firstWord = words[0];
      
      if (wordToNum[firstWord] !== undefined) {
        qty = wordToNum[firstWord];
        command = words.slice(1).join(" ").trim();
      } else {
        const digitMatch = command.match(/^(\d+)\s+/);
        if (digitMatch) {
          qty = parseInt(digitMatch[1], 10) || 1;
          command = command.substring(digitMatch[0].length).trim();
        }
      }
      
      const spokenName = command.trim();
      if (spokenName.length >= 2) {
        // Find matching menu item
        let matchedItem = state.menuItems.find(item => item.active && item.name.toLowerCase().trim() === spokenName);
        if (!matchedItem) {
          // substring match
          matchedItem = state.menuItems.find(item => item.active && (item.name.toLowerCase().includes(spokenName) || spokenName.includes(item.name.toLowerCase())));
        }
        if (!matchedItem) {
          // word split match
          const spokenWords = spokenName.split(/\s+/).filter(w => w.length > 2);
          if (spokenWords.length > 0) {
            matchedItem = state.menuItems.find(item => item.active && spokenWords.every(word => item.name.toLowerCase().includes(word)));
          }
        }
        
        if (matchedItem) {
          if (state.activeView === "pos") {
            const portionsLeft = matchedItem.portionsAvailable !== undefined && matchedItem.portionsAvailable !== null ? Number(matchedItem.portionsAvailable) : null;
            const cat = state.categories.find(c => c.id === matchedItem.categoryId);
            const catPortionsLeft = cat?.portionsAvailable !== undefined && cat?.portionsAvailable !== null ? Number(cat.portionsAvailable) : null;
            
            const line = state.cart.find((cartItem) => cartItem.id === matchedItem.id);
            const nextQty = (line ? line.quantity : 0) + qty;
            
            if (portionsLeft !== null && nextQty > portionsLeft) {
              showInfo({ title: "Out of Stock Warning", message: `Cannot add ${qty} portions. Only ${portionsLeft} portions left of ${matchedItem.name}.` });
              return;
            }
            if (catPortionsLeft !== null && nextQty > catPortionsLeft) {
              showInfo({ title: "Category Out of Stock Warning", message: `Cannot add ${qty} portions. Only ${catPortionsLeft} portions left for category ${cat.name}.` });
              return;
            }
            
            if (line) line.quantity = nextQty;
            else state.cart.push({ id: matchedItem.id, code: matchedItem.code || "", name: matchedItem.name, price: matchedItem.price, quantity: qty });
            state.focusQtyId = matchedItem.id;
            state.voiceFeedback = `✅ Added ${qty}x ${matchedItem.name} to cart`;
            showToast(`Added ${qty}x ${matchedItem.name} to cart`, "success");
            speakConfirmation(`Added ${qty} ${matchedItem.name}`);
            render();
          } else if (state.activeView === "tables") {
            const line = state.tableCart.find((cartItem) => cartItem.id === matchedItem.id);
            const nextQty = (line ? line.quantity : 0) + qty;
            
            if (line) line.quantity = nextQty;
            else state.tableCart.push({ id: matchedItem.id, code: matchedItem.code || "", name: matchedItem.name, price: matchedItem.price, quantity: qty });
            state.focusTableQtyId = matchedItem.id;
            state.voiceFeedback = `✅ Added ${qty}x ${matchedItem.name} to table cart`;
            showToast(`Added ${qty}x ${matchedItem.name} to table cart`, "success");
            speakConfirmation(`Added ${qty} ${matchedItem.name}`);
            render();
          }
        } else {
          state.voiceFeedback = `Could not find any item matching "${spokenName}"`;
          render();
        }
      }
      return;
    }

    // Check for the word "ready", Tamil equivalent "ரெடி" or "முடிந்தது"
    if (transcript.includes("ready") || transcript.includes("ரெடி") || transcript.includes("முடிந்தது")) {
      const match = transcript.match(/\d+/);
      if (match) {
        const orderNumber = match[0];
        const activeKots = state.kots.filter((k) => k.branchId === state.activeBranchId && k.status !== "served");
        
        // Find a matching KOT that matches this dailyOrderNo or matches/ends with billNo
        const matchedKot = activeKots.find((k) => {
          if (k.dailyOrderNo && String(k.dailyOrderNo) === orderNumber) return true;
          const cleanBillNo = k.billNo.replace(/\D/g, "");
          return cleanBillNo === orderNumber || k.billNo.toLowerCase().includes(orderNumber);
        });

        if (matchedKot) {
          const displayId = matchedKot.dailyOrderNo ? `#${matchedKot.dailyOrderNo}` : matchedKot.billNo;
          if (matchedKot.status === "ready") {
            state.voiceFeedback = `Order ${displayId} is already ready.`;
          } else {
            state.voiceFeedback = `Heard: "${transcript}" -> Marking Order ${displayId} ready...`;
            render();
            try {
              await api(`/api/kots/${matchedKot.id}`, {
                method: "PATCH",
                body: JSON.stringify({ status: "ready" })
              });
              await refreshOperationalData();
              state.voiceFeedback = `✅ Success: Order ${displayId} marked as Ready!`;
              speakConfirmation(`Order ${matchedKot.dailyOrderNo || matchedKot.billNo} is ready`);
            } catch (err) {
              state.voiceFeedback = `⚠️ Error updating Order ${displayId}`;
            }
          }
          render();
        } else {
          state.voiceFeedback = `Could not find any active order matching "${orderNumber}"`;
          render();
        }
      } else {
        state.voiceFeedback = `Heard "ready", but couldn't detect any order number.`;
        render();
      }
    }
  };

  recognition.onerror = (event) => {
    console.error("Speech Recognition Error:", event.error);
    if (event.error === "not-allowed") {
      state.voiceError = "Microphone access denied.";
      state.voiceActive = false;
    } else if (event.error === "no-speech") {
      // Ignore silence
    } else {
      state.voiceError = `Error: ${event.error}`;
    }
    render();
  };

  recognition.onend = () => {
    if (state.voiceActive) {
      try {
        recognition.start();
      } catch (err) {
        console.error("Failed to restart speech recognition:", err);
      }
    } else {
      render();
    }
  };
}

function speakConfirmation(text) {
  if (window.speechSynthesis) {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.rate = 1.0;
    window.speechSynthesis.speak(utterance);
  }
}

function startVoiceControl() {
  if (!recognition) {
    initSpeechRecognition();
  }
  if (recognition && !state.voiceActive) {
    try {
      recognition.start();
    } catch (err) {
      state.voiceError = "Failed to start speech recognition.";
      render();
    }
  }
}

function stopVoiceControl() {
  if (recognition) {
    state.voiceActive = false;
    state.voiceFeedback = "Voice control disabled.";
    try {
      recognition.stop();
    } catch (err) {}
    render();
  }
}

