async function renderRevenueTrendsChart() {
  const chartContainer = document.getElementById("revenue-trends-chart");
  const statusEl = document.getElementById("chart-loading-status");
  if (!chartContainer) return;

  try {
    const currentDate = new Date(state.dashboardDate);
    const formatYMD = (date) => {
      const y = date.getFullYear();
      const m = String(date.getMonth() + 1).padStart(2, "0");
      return `${y}-${m}`;
    };
    
    const currentMonth = formatYMD(currentDate);
    
    // Get previous month
    const prevDate = new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 15);
    const prevMonth = formatYMD(prevDate);
    
    const branchId = state.activeBranchId || "all";
    
    if (statusEl) statusEl.textContent = "Fetching sales logs...";
    
    // Fetch both months in parallel
    const [currentRes, prevRes] = await Promise.all([
      api(`/api/reports/daily-ledger?branchId=${branchId}&month=${currentMonth}`).catch(() => null),
      api(`/api/reports/daily-ledger?branchId=${branchId}&month=${prevMonth}`).catch(() => null)
    ]);
    
    // Combine and sort
    const combinedLedger = [
      ...(prevRes?.ledger || []),
      ...(currentRes?.ledger || [])
    ];
    
    // Sort chronological
    const sorted = combinedLedger.sort((a, b) => a.date.localeCompare(b.date));
    
    // Filter up to the current dashboardDate, and then take last 30 items
    const upToToday = sorted.filter(item => item.date <= state.dashboardDate);
    const last30Days = upToToday.slice(-30);
    
    if (last30Days.length === 0) {
      chartContainer.innerHTML = `<div class="muted" style="font-size: 13px; padding: 40px; text-align: center;">No sales history available up to this date to plot trends.</div>`;
      if (statusEl) {
        statusEl.textContent = "No Data";
        statusEl.className = "status warning";
        statusEl.style.color = "#fbbf24";
        statusEl.style.background = "rgba(251,191,36,0.1)";
        statusEl.style.borderColor = "rgba(251,191,36,0.2)";
      }
      return;
    }
    
    if (statusEl) {
      statusEl.textContent = "Rendering...";
    }
    
    // Render Recharts using React
    if (typeof window.React === "undefined" || typeof window.ReactDOM === "undefined" || typeof window.Recharts === "undefined") {
      setTimeout(renderRevenueTrendsChart, 500);
      return;
    }
    
    const el = window.React.createElement;
    const root = window.ReactDOM.createRoot(chartContainer);
    
    const formattedData = last30Days.map(item => ({
      date: item.date,
      sales: Number(item.sales || 0),
      label: (() => {
        try {
          const parts = item.date.split("-");
          const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
          const monthIdx = Number(parts[1]) - 1;
          return `${parts[2]} ${months[monthIdx] || ""}`;
        } catch (e) {
          return item.date;
        }
      })()
    }));
    
    root.render(
      el(window.Recharts.ResponsiveContainer, { width: "100%", height: 350 },
        el(window.Recharts.LineChart, { data: formattedData, margin: { top: 15, right: 25, left: 10, bottom: 15 } },
          el(window.Recharts.CartesianGrid, { strokeDasharray: "3 3", stroke: "rgba(24,21,18,0.08)" }),
          el(window.Recharts.XAxis, { 
            dataKey: "label", 
            stroke: "var(--muted)", 
            tick: { fill: "var(--muted)", fontSize: 11, fontWeight: 500 },
            dy: 10
          }),
          el(window.Recharts.YAxis, { 
            stroke: "var(--muted)", 
            tick: { fill: "var(--muted)", fontSize: 11, fontWeight: 500 },
            tickFormatter: (value) => `₹${value >= 1000 ? (value / 1000).toFixed(0) + "k" : value}`,
            dx: -5
          }),
          el(window.Recharts.Tooltip, { 
            contentStyle: { 
              background: "#ffffff", 
              border: "1px solid var(--line)", 
              borderRadius: "8px",
              color: "var(--ink)",
              fontSize: "12.5px",
              boxShadow: "var(--shadow)"
            },
            formatter: (value) => [`₹${Number(value).toLocaleString()}`, "Sales Revenue"]
          }),
          el(window.Recharts.Legend, { 
            wrapperStyle: { fontSize: "12.5px", marginTop: "10px", color: "var(--muted)" } 
          }),
          el(window.Recharts.Line, { 
            type: "monotone", 
            dataKey: "sales", 
            name: "Daily Revenue Trend", 
            stroke: "var(--brand)", // brand gold
            strokeWidth: 3, 
            activeDot: { r: 8, strokeWidth: 1, stroke: "var(--brand)" },
            dot: { r: 4, stroke: "var(--brand)", strokeWidth: 2, fill: "#ffffff" }
          })
        )
      )
    );
    
    if (statusEl) {
      statusEl.textContent = `Plotting ${last30Days.length} days`;
      statusEl.className = "status success";
      statusEl.style.color = "#4ade80";
      statusEl.style.background = "rgba(74,222,128,0.1)";
      statusEl.style.borderColor = "rgba(74,222,128,0.2)";
    }
    
  } catch (err) {
    console.error("Error loading revenue trends chart:", err);
    chartContainer.innerHTML = `<div class="alert danger" style="padding: 20px;">Failed to render Revenue Trends chart: ${err.message}</div>`;
    if (statusEl) {
      statusEl.textContent = "Error";
      statusEl.className = "status danger";
      statusEl.style.color = "#f87171";
      statusEl.style.background = "rgba(248,113,113,0.1)";
      statusEl.style.borderColor = "rgba(248,113,113,0.2)";
    }
  }
}

function bindBillsPaginationEvents() {
  document.querySelector("#btnPrevBills")?.addEventListener("click", () => {
    if (state.billsPage > 1) {
      state.billsPage--;
      updateBillsTable();
    }
  });
  document.querySelector("#btnNextBills")?.addEventListener("click", () => {
    const totalPages = Math.ceil(getFilteredBills().length / state.billsLimit) || 1;
    if (state.billsPage < totalPages) {
      state.billsPage++;
      updateBillsTable();
    }
  });
}

