  document.querySelector("#btnAutoCalculateRestock")?.addEventListener("click", async () => {
    const supplierId = state.editing.orderSupplierId || activeSuppliers()[0]?.id || "";
    if (!supplierId) {
      showInfo({ title: "No Supplier Selected", message: "Please select a supplier first." });
      return;
    }
    try {
      const recommendations = await api(`/api/inventory/reorder-recommendations?supplierId=${supplierId}&branchId=${state.activeBranchId || "all"}`);
      // Filter out items that are sufficiently stocked
      const needsRestock = recommendations.filter((r) => !r.isSufficientlyStocked && r.recommendedQty > 0);
      
      if (needsRestock.length === 0) {
        showInfo({
          title: "👍 Stock Levels Sufficient",
          message: "All items mapped to this supplier are currently sufficiently stocked above their reorder levels plus consumption buffers."
        });
        return;
      }
      
      state.purchaseOrderLines = needsRestock.map((r) => ({
        inventoryId: r.inventoryId,
        name: r.name,
        unit: r.unit,
        quantity: r.recommendedQty
      }));
      
      showInfo({
        title: "🤖 Restock Quantities Calculated",
        message: `Automatically loaded ${needsRestock.length} under-stocked item(s) based on minimum thresholds and average daily usage rates.`
      });
      render();
    } catch (err) {
      showInfo({ title: "Calculation Error", message: err.message });
    }
  });

