  const expCatSelect = document.querySelector("#expenseCategorySelect");
  if (expCatSelect) {
    const customInput = document.querySelector("#expenseCustomCategory");
    const employeeSelect = document.querySelector("#expenseEmployeeSelect");
    
    if (customInput) {
      if (expCatSelect.value === "Others") {
        customInput.setAttribute("required", "required");
      } else {
        customInput.removeAttribute("required");
      }
    }
    if (employeeSelect) {
      if (expCatSelect.value === "Salary") {
        employeeSelect.setAttribute("required", "required");
      } else {
        employeeSelect.removeAttribute("required");
      }
    }
    
    expCatSelect.addEventListener("change", (e) => {
      const customField = document.querySelector("#customCategoryField");
      const customInput = document.querySelector("#expenseCustomCategory");
      const employeeField = document.querySelector("#expenseEmployeeSelectField");
      const employeeSelect = document.querySelector("#expenseEmployeeSelect");
      
      if (customField) {
        if (e.target.value === "Others") {
          customField.style.display = "block";
          if (customInput) customInput.setAttribute("required", "required");
        } else {
          customField.style.display = "none";
          if (customInput) {
            customInput.removeAttribute("required");
            customInput.value = "";
          }
        }
      }
      
      if (employeeField) {
        if (e.target.value === "Salary") {
          employeeField.style.display = "block";
          if (employeeSelect) employeeSelect.setAttribute("required", "required");
        } else {
          employeeField.style.display = "none";
          if (employeeSelect) {
            employeeSelect.removeAttribute("required");
            employeeSelect.value = "";
          }
        }
      }
    });

    const updateExpenseSalarySettlement = async () => {
      const empSelect = document.querySelector("#expenseEmployeeSelect");
      const settlementCheck = document.querySelector("#expenseSalarySettlementCheck");
      const balanceDisplay = document.querySelector("#expenseEmployeeBalanceDisplay");
      const amountInput = document.querySelector("#expenseForm input[name='amount']");
      
      if (!empSelect || !settlementCheck || !balanceDisplay || !amountInput) return;
      
      const userId = empSelect.value;
      if (!userId) {
        balanceDisplay.style.display = "none";
        balanceDisplay.textContent = "";
        return;
      }
      
      balanceDisplay.style.display = "block";
      balanceDisplay.textContent = "Calculating balance...";
      
      const branchId = state.activeBranchId || "all";
      const date = state.dashboardDate || getSyncDate().toISOString().slice(0, 10);
      const excludeId = state.editing.expense || null;
      
      try {
        const res = await api(`/api/reports/payroll?branchId=${branchId}&date=${date}&period=month`);
        const emp = (res.payroll || []).find(u => u.userId === userId);
        let balance = emp ? Number(emp.balanceDue || 0) : 0;
        
        if (excludeId) {
          const exp = state.operatingExpenses.find(e => e.id === excludeId);
          if (exp && exp.category === "Salary" && exp.userId === userId) {
            balance += Number(exp.amount || 0);
          }
        }
        
        balance = Math.max(0, balance);
        balanceDisplay.textContent = `Current Outstanding Dues: ₹${balance.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
        
        if (settlementCheck.checked) {
          amountInput.value = balance.toFixed(2);
          amountInput.readOnly = true;
        } else {
          amountInput.readOnly = false;
        }
      } catch (err) {
        console.error(err);
        balanceDisplay.textContent = "Error calculating balance";
      }
    };

    const empSelect = document.querySelector("#expenseEmployeeSelect");
    if (empSelect) {
      empSelect.addEventListener("change", updateExpenseSalarySettlement);
    }
    const settlementCheck = document.querySelector("#expenseSalarySettlementCheck");
    if (settlementCheck) {
      settlementCheck.addEventListener("change", updateExpenseSalarySettlement);
    }

    if (expCatSelect.value === "Salary" && employeeSelect && employeeSelect.value) {
      setTimeout(updateExpenseSalarySettlement, 50);
    }
  }

