async function syncOfflineOrders(force = false) {
  if (!force && !navigator.onLine) return;
  if (state.networkMode === "offline") return;

  const queue = (() => { try { return JSON.parse(localStorage.getItem("offline_orders_queue") || "[]"); } catch (e) { return []; } })();
  if (queue.length === 0) return;

  console.log(`[Offline Sync] Differential Sync: sending ${queue.length} order deltas...`);

  try {
    const payload = {
      deltas: queue.map(order => ({
        id: order.id,
        billNo: order.billNo,
        branchId: order.branchId,
        orderType: order.orderType,
        tableNo: order.tableNo,
        customerName: order.customerName,
        customerPhone: order.customerPhone,
        deliveryAddress: order.deliveryAddress,
        deliveryFee: order.deliveryFee,
        items: order.lines.map(line => ({ menuItemId: line.menuItemId, quantity: line.quantity })),
        discountPercent: order.discountPercent,
        payments: order.payments,
        createdAt: order.createdAt
      }))
    };

    const response = await api("/api/orders/sync-deltas", {
      method: "POST",
      body: JSON.stringify(payload),
      showLoader: false
    });

    const results = response.results || [];
    const remaining = [];
    let syncedCount = 0;
    let duplicateCount = 0;
    let errorMessages = [];

    queue.forEach(order => {
      const match = results.find(r => r.id === order.id);
      if (match) {
        if (match.status === "success") {
          syncedCount++;
        } else if (match.status === "ignored_duplicate") {
          duplicateCount++;
        } else {
          order.error = match.error || "Validation failed on server";
          errorMessages.push(`Order ${order.billNo || "Unknown"}: ${order.error}`);
          remaining.push(order);
        }
      } else {
        remaining.push(order);
      }
    });

    localStorage.setItem("offline_orders_queue", JSON.stringify(remaining));

    if (syncedCount > 0 || duplicateCount > 0) {
      const successMsg = `🔄 Differential Sync Completed: successfully synchronized ${syncedCount} offline orders${duplicateCount > 0 ? ` (${duplicateCount} duplicate(s) bypassed)` : ""}!`;
      showNotificationToast(successMsg);
      // Run refreshOperationalData silently in background to avoid showing a blocking "Processing..." modal to users
      await refreshOperationalData(true).catch(() => {});
      await refreshMasters().catch(() => {});
      render();
    }

    if (errorMessages.length > 0) {
      showToast(`Warning: ${errorMessages.length} order(s) failed sync due to server validation. Check Queued Orders.`, "warning");
    }
  } catch (err) {
    console.error("[Offline Sync] Differential Sync failed completely:", err);
    logConnectionError("sync_error", err);
    throw err;
  }
}

